<template>
  <div class="office-page"><AppSidebar/><main class="office-main">
    <header class="page-header"><div><h2>{{ title }}</h2><p>{{ subtitle }}</p></div><el-tag v-if="workspaceId" type="success">{{ activeWorkspace.name }}</el-tag></header>
    <el-alert v-if="!isOffice" title="请先选择智慧办公工作空间" type="warning" :closable="false" show-icon/>
    <template v-else>
      <section v-if="section==='meetings'"><div class="toolbar"><el-button type="primary" icon="el-icon-plus" @click="openCreate">新建会议</el-button><el-button @click="load">刷新</el-button></div><el-table :data="meetings" v-loading="loading" row-key="id"><el-table-column label="会议主题" min-width="220"><template slot-scope="{row}"><button class="title-link" @click="openMeeting(row)">{{ row.title }}</button></template></el-table-column><el-table-column label="会议时间" width="230"><template slot-scope="{row}">{{ formatRange(row.start_time,row.end_time) }}</template></el-table-column><el-table-column prop="location" label="地点" min-width="120"/><el-table-column label="状态" width="100" align="center"><template slot-scope="{row}"><el-tag size="mini">{{ status(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="100" align="center"><template slot-scope="{row}"><el-button type="text" class="danger" @click="removeMeeting(row)">删除</el-button></template></el-table-column></el-table></section>
      <section v-else-if="section==='schedules'" v-loading="loading"><div class="calendar-head"><div><el-button size="mini" @click="previousMonth">‹</el-button><strong>{{ monthLabel }}</strong><el-button size="mini" @click="nextMonth">›</el-button><el-button size="mini" @click="calendarDate=new Date()">今天</el-button></div><el-radio-group v-model="scheduleView" size="small"><el-radio-button label="month">月视图</el-radio-button><el-radio-button label="list">列表视图</el-radio-button></el-radio-group></div><el-calendar v-if="scheduleView==='month'" v-model="calendarDate" class="office-calendar"><template slot="dateCell" slot-scope="{data}"><div class="day-cell" :class="{today:data.isSelected}"><span>{{ data.day.slice(-2) }}</span><button v-for="item in eventsFor(data.day).slice(0,2)" :key="item.id" class="event-chip" :class="item.event_type" @click.stop="selectSchedule(item)">{{ item.title }}</button><small v-if="eventsFor(data.day).length>2">+{{ eventsFor(data.day).length-2 }} 项</small></div></template></el-calendar><el-table v-else :data="schedules" stripe><el-table-column label="时间" width="180"><template slot-scope="{row}">{{ formatRange(row.start_time,row.end_time) }}</template></el-table-column><el-table-column prop="title" label="事项"/><el-table-column label="类型" width="100"><template slot-scope="{row}">{{ typeLabel(row.event_type) }}</template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="{row}">{{ status(row.status) }}</template></el-table-column></el-table></section>
      <section v-else-if="section==='documents'"><div class="toolbar"><el-button type="primary" @click="openCreate">新建公文</el-button><el-button @click="load">刷新</el-button></div><el-table :data="documents" v-loading="loading" stripe><el-table-column label="标题" min-width="260"><template slot-scope="{row}"><button class="title-link" @click="viewDocument(row)">{{ row.title }}</button></template></el-table-column><el-table-column label="状态" width="120" align="center"><template slot-scope="{row}">{{ status(row.status) }}</template></el-table-column><el-table-column label="操作" width="180" align="center"><template slot-scope="{row}"><el-button :disabled="row.status!=='draft'" type="text" @click="submit(row)">提交审批</el-button><el-button :disabled="row.status!=='approved'" type="text" @click="publish(row)">发布</el-button></template></el-table-column></el-table></section>
      <section v-else-if="section==='approvals'"><div class="toolbar"><el-button @click="load">刷新</el-button></div><el-table :data="approvals" v-loading="loading" stripe><el-table-column label="审批事项" min-width="260"><template slot-scope="{row}"><button class="title-link" @click="viewApproval(row)">{{ row.title }}</button></template></el-table-column><el-table-column label="状态" width="110" align="center"><template slot-scope="{row}"><el-tag size="mini">{{ status(row.status) }}</el-tag></template></el-table-column><el-table-column prop="created_at" label="提交时间" width="180" align="center"/><el-table-column label="操作" width="150" align="center"><template slot-scope="{row}"><el-button v-if="row.can_handle" type="success" size="mini" @click="approve(row)">通过</el-button><el-button v-if="row.can_handle" type="danger" size="mini" @click="reject(row)">驳回</el-button><span v-if="!row.can_handle" class="muted">无需操作</span></template></el-table-column></el-table></section>
      <section v-else><div class="dashboard"><el-card v-for="card in dashboardCards" :key="card.label"><strong>{{card.value}}</strong><span>{{card.label}}</span></el-card></div><el-card class="ai-quick"><div class="ai-quick-head"><div><h3>AI 办公助手</h3><p>汇总会议与公文，生成可直接发送给公共聊天的任务提示词。</p></div><div><el-button type="primary" icon="el-icon-magic-stick" @click="openAiPrompt('weekly')">AI 生成周报 / PPT 提示词</el-button><el-button @click="openAiPrompt('document')">根据会议生成公文提示词</el-button></div></div></el-card></section>
    </template>
  </main>
  <el-dialog :title="section==='meetings'?'新建会议':'新建公文'" :visible.sync="createVisible" width="520px"><el-form :model="createForm" label-width="82px"><el-form-item label="标题"><el-input v-model="createForm.title"/></el-form-item><template v-if="section==='meetings'"><el-form-item label="开始时间"><el-date-picker v-model="createForm.start_time" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="createForm.end_time" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss"/></el-form-item><el-form-item label="参会成员"><el-select v-model="createForm.participants" multiple placeholder="选择要通知的成员" style="width:100%"><el-option v-for="member in officeMembers" :key="member.user_id" :label="member.display_name+' · '+statusRole(member.role)" :value="{user_id:member.user_id,display_name:member.display_name}"/></el-select></el-form-item><el-form-item label="地点"><el-input v-model="createForm.location"/></el-form-item></template><el-form-item v-else label="正文"><el-input v-model="createForm.content" type="textarea" :rows="7"/></el-form-item></el-form><span slot="footer"><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></span></el-dialog>
  <el-dialog :visible.sync="detailVisible" :title="selectedMeeting&&selectedMeeting.title" width="760px" top="5vh"><div v-if="selectedMeeting" class="meeting-detail"><el-descriptions :column="2" border><el-descriptions-item label="会议时间">{{formatRange(selectedMeeting.start_time,selectedMeeting.end_time)}}</el-descriptions-item><el-descriptions-item label="地点">{{selectedMeeting.location||'-'}}</el-descriptions-item><el-descriptions-item label="状态">{{status(selectedMeeting.status)}}</el-descriptions-item><el-descriptions-item label="行动项">{{actionItems.length}} 项</el-descriptions-item></el-descriptions><el-divider>会议纪要与行动项</el-divider><el-steps :active="minutesStep" simple><el-step title="会议材料"/><el-step title="AI 草稿"/><el-step title="确认保存"/></el-steps><div v-show="minutesStep===0" class="step-panel"><p>粘贴转写或会议要点，AI 只生成草稿，不会直接写入数据。</p><el-input v-model="meetingMaterial" type="textarea" :rows="8" placeholder="粘贴会议材料"/><el-button type="primary" :loading="draftLoading" @click="generateDraft">根据材料生成草稿</el-button></div><div v-show="minutesStep===1" class="step-panel"><el-form label-position="top"><el-form-item label="会议纪要"><el-input v-model="meetingForm.minutes" type="textarea" :rows="7"/></el-form-item><el-form-item label="会议决议（每行一项）"><el-input v-model="resolutionsText" type="textarea" :rows="3"/></el-form-item></el-form><el-button @click="minutesStep=0">返回材料</el-button><el-button type="primary" @click="minutesStep=2">下一步：确认行动项</el-button></div><div v-show="minutesStep===2" class="step-panel"><el-table :data="aiActionItems" empty-text="AI 未识别出行动项，可在下方手动新增"><el-table-column prop="title" label="任务"/><el-table-column prop="assignee_name" label="负责人" width="120"/><el-table-column prop="due_date" label="截止时间" width="170"/></el-table><el-divider>新增 / 编辑行动项</el-divider><el-row :gutter="10"><el-col :span="10"><el-input v-model="actionForm.title" placeholder="任务"/></el-col><el-col :span="6"><el-input v-model="actionForm.assignee_name" placeholder="负责人"/></el-col><el-col :span="8"><el-date-picker v-model="actionForm.due_date" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss" placeholder="截止时间"/></el-col></el-row><el-checkbox v-model="actionForm.create_schedule">同步到日程</el-checkbox><el-button type="success" size="mini" @click="addAction">保存该行动项</el-button><el-divider>已保存行动项</el-divider><el-table :data="actionItems" size="mini"><el-table-column prop="title" label="任务"/><el-table-column prop="assignee_name" label="负责人"/><el-table-column prop="due_date" label="截止时间"/></el-table><div class="detail-footer"><el-button @click="minutesStep=1">返回编辑</el-button><el-button type="primary" @click="saveMinutes">确认保存纪要与决议</el-button></div></div></div><span slot="footer"><el-button @click="detailVisible=false">关闭</el-button></span></el-dialog>
  <el-dialog title="审批事项详情" :visible.sync="approvalVisible" width="680px"><div v-if="approvalDetail"><h3>{{approvalDetail.document&&approvalDetail.document.title}}</h3><pre class="doc-content">{{approvalDetail.document&&approvalDetail.document.content}}</pre><el-divider>审批记录</el-divider><p v-for="(item,index) in approvalDetail.history||[]" :key="index">第 {{item.step}} 步：{{item.action}} {{item.comment||''}}</p></div></el-dialog>
  <el-dialog title="公文详情" :visible.sync="documentVisible" width="680px"><div v-if="documentDetail"><el-descriptions :column="2" border><el-descriptions-item label="标题">{{documentDetail.title}}</el-descriptions-item><el-descriptions-item label="状态">{{status(documentDetail.status)}}</el-descriptions-item><el-descriptions-item label="公文类型">{{documentDetail.document_type||'-'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{documentDetail.created_at||'-'}}</el-descriptions-item></el-descriptions><el-divider>正文</el-divider><pre class="doc-content">{{documentDetail.content}}</pre></div></el-dialog>
  <el-dialog title="AI 办公快捷任务" :visible.sync="aiPromptVisible" width="680px"><p>复制下方提示词后，可前往公共聊天继续生成和打磨内容。</p><el-input v-model="aiPrompt" type="textarea" :rows="11"/><span slot="footer"><el-button @click="copyAiPrompt">复制提示词</el-button><el-button type="primary" @click="goChat">前往公共聊天</el-button></span></el-dialog>
</div></template>
<script>
import AppSidebar from '../components/Sidebar/index.vue'
const meta={meetings:['会议管理','从会议开始，沉淀纪要、任务和公文'],schedules:['日程管理','查看会议与行动项的时间安排'],documents:['公文管理','起草、审批和发布正式公文'],approvals:['审批流程','处理待办审批并查看关联公文']}
export default {name:'OfficeWorkspace',components:{AppSidebar},data:()=>({createVisible:false,createForm:{},detailVisible:false,selectedMeeting:null,meetingForm:{},meetingMaterial:'',resolutionsText:'',minutesStep:0,draftLoading:false,aiActionItems:[],actionItems:[],actionForm:{create_schedule:true},calendarDate:new Date(),scheduleView:'month',approvalVisible:false,approvalDetail:null,documentVisible:false,documentDetail:null,aiPromptVisible:false,aiPrompt:'',loadVersion:0}),computed:{section(){return this.$route.name},title(){return(meta[this.section]||[])[0]},subtitle(){return(meta[this.section]||[])[1]},activeWorkspace(){return this.$store.getters['workspace/activeWorkspace']||{}},workspaceId(){return this.activeWorkspace.id},isOffice(){return this.activeWorkspace.domain==='office'},loading(){return this.$store.state.office.loading},meetings(){return this.$store.state.office.meetings},schedules(){return this.$store.state.office.schedules},documents(){return this.$store.state.office.documents},approvals(){return this.$store.state.office.approvals},officeMembers(){return (this.$store.state.office.organization||{members:[]}).members},monthLabel(){return `${this.calendarDate.getFullYear()} 年 ${this.calendarDate.getMonth()+1} 月`},dashboardCards(){const d=this.$store.state.office.dashboard||{},a=d.action_items||{},docs=d.documents_by_status||{};return[{label:'本周会议',value:d.meetings_this_week||0},{label:'待处理审批',value:d.pending_approvals||0},{label:'任务完成率',value:`${a.completion_rate||0}%`},{label:'已发布公文',value:docs.published||0}]}},watch:{'$route.fullPath':{handler(){this.load()},immediate:true},workspaceId(){this.load()}},methods:{async load(){if(!this.isOffice||!this.workspaceId)return;const v=++this.loadVersion,action={meetings:'loadMeetings',schedules:'loadSchedules',documents:'loadDocuments',approvals:'loadApprovals',reports:'loadDashboard'}[this.section];if(!action)return;this.$store.commit('office/SET_LOADING',true);try{await this.$store.dispatch(`office/${action}`,this.workspaceId)}finally{if(v===this.loadVersion)this.$store.commit('office/SET_LOADING',false)}},async openCreate(){this.createForm={participants:[]};if(this.section==='meetings')await this.$store.dispatch('office/loadOrganization',this.workspaceId);this.createVisible=true},async create(){const data={...this.createForm,workspace_id:this.workspaceId},action=this.section==='meetings'?'createMeeting':'createDocument';if(action==='createDocument')data.document_type='notice';await this.$store.dispatch(`office/${action}`,data);this.createVisible=false;this.$message.success('已保存')},async openMeeting(row){const d=await this.$store.dispatch('office/getMeeting',row.id);this.selectedMeeting=d;this.meetingForm={minutes:d.minutes||''};this.resolutionsText=(d.resolutions||[]).join('\n');this.meetingMaterial=d.transcript||'';this.actionItems=d.action_items||[];this.aiActionItems=[];this.actionForm={create_schedule:true};this.minutesStep=0;this.detailVisible=true},async generateDraft(){if(this.meetingMaterial.trim().length<10)return this.$message.warning('请先输入会议材料');this.draftLoading=true;try{const d=await this.$store.dispatch('office/generateMeetingDraft',{title:this.selectedMeeting.title,material:this.meetingMaterial});this.meetingForm.minutes=d.minutes||'';this.resolutionsText=(d.resolutions||[]).join('\n');this.aiActionItems=d.action_items||[];this.minutesStep=1;if(d.warning)this.$message.warning(d.warning)}finally{this.draftLoading=false}},async saveMinutes(){await this.$store.dispatch('office/updateMeeting',{id:this.selectedMeeting.id,data:{minutes:this.meetingForm.minutes,resolutions:this.resolutionsText.split('\n').filter(Boolean)},workspaceId:this.workspaceId});this.$message.success('会议纪要已保存')},async addAction(){if(!this.actionForm.title)return this.$message.warning('请填写任务');await this.$store.dispatch('office/createActionItem',{meetingId:this.selectedMeeting.id,data:this.actionForm,workspaceId:this.workspaceId});const d=await this.$store.dispatch('office/getMeeting',this.selectedMeeting.id);this.actionItems=d.action_items||[];this.actionForm={create_schedule:true};this.$message.success('行动项已保存')},async removeMeeting(row){try{await this.$confirm(`确定删除“${row.title}”吗？`,'删除会议',{type:'warning'});await this.$store.dispatch('office/deleteMeeting',{id:row.id,workspaceId:this.workspaceId});this.$message.success('已删除')}catch{}},eventsFor(day){return this.schedules.filter(x=>(x.start_time||'').slice(0,10)===day)},previousMonth(){this.calendarDate=new Date(this.calendarDate.getFullYear(),this.calendarDate.getMonth()-1,1)},nextMonth(){this.calendarDate=new Date(this.calendarDate.getFullYear(),this.calendarDate.getMonth()+1,1)},selectSchedule(item){if(item.meeting_id){const m=this.meetings.find(x=>x.id===item.meeting_id);if(m)this.openMeeting(m)}},async viewApproval(row){this.approvalDetail=await this.$store.dispatch('office/getApproval',row.id);this.approvalVisible=true},async viewDocument(row){this.documentDetail=await this.$store.dispatch('office/getDocument',row.id);this.documentVisible=true},async approve(row){await this.$store.dispatch('office/approve',{id:row.id,data:{},workspaceId:this.workspaceId});this.load()},async reject(row){try{const {value}=await this.$prompt('请填写驳回意见','驳回审批',{inputPattern:/\S+/,inputErrorMessage:'驳回意见不能为空'});await this.$store.dispatch('office/reject',{id:row.id,data:{comment:value},workspaceId:this.workspaceId});this.load()}catch{}},async submit(row){await this.$store.dispatch('office/submitDocument',{id:row.id,data:{},workspaceId:this.workspaceId});this.load()},async publish(row){await this.$store.dispatch('office/publishDocument',{id:row.id,workspaceId:this.workspaceId});this.load()},async openAiPrompt(kind){await Promise.all([this.$store.dispatch('office/loadMeetings',this.workspaceId),this.$store.dispatch('office/loadDocuments',this.workspaceId)]);const meetings=this.meetings.slice(0,5).map(x=>`- ${x.title}（${this.formatRange(x.start_time,x.end_time)}）`).join('\n')||'- 暂无会议',docs=this.documents.slice(0,5).map(x=>`- ${x.title}（${this.status(x.status)}）`).join('\n')||'- 暂无公文';this.aiPrompt=kind==='weekly'?`请根据以下智慧办公工作记录，生成一份结构清晰的本周周报，并给出 5 页 PPT 汇报大纲。\n\n会议：\n${meetings}\n\n公文：\n${docs}\n\n请包含：本周进展、关键决议、待办与负责人、风险和下周计划。`:`请根据以下会议与公文背景，起草一份正式办公公文。请先给出标题、主送单位、正文、落款和日期；措辞规范、要点清晰。\n\n会议：\n${meetings}\n\n已有公文：\n${docs}`;this.aiPromptVisible=true},async copyAiPrompt(){try{await navigator.clipboard.writeText(this.aiPrompt);this.$message.success('提示词已复制')}catch(e){this.$message.info('请手动复制提示词')}},goChat(){this.aiPromptVisible=false;this.$router.push('/dashboard')},formatRange(a,b){if(!a)return '-';return `${String(a).replace('T',' ').slice(0,16)} ～ ${String(b||'').replace('T',' ').slice(0,16)}`},status(s){return({scheduled:'待召开',ongoing:'进行中',completed:'已完成',cancelled:'已取消',draft:'草稿',reviewing:'审批中',approved:'已批准',published:'已发布',pending:'待处理',done:'已完成',rejected:'已驳回'})[s]||s},statusRole(s){return({member:'普通成员',team_lead:'直属领导',department_head:'部门负责人'})[s]||s},typeLabel(t){return({meeting:'会议',task:'任务',reminder:'提醒',other:'其他'})[t]||t}}}
</script>
<style scoped>
.office-page{display:flex;height:100vh;box-sizing:border-box;overflow:hidden;padding:12px;gap:12px;background:#f5f7fb}.office-main{flex:1;min-width:0;overflow-y:auto;padding:24px;background:#fff;border-radius:12px}.page-header{display:flex;justify-content:space-between;border-bottom:1px solid #edf0f5;margin-bottom:18px;padding-bottom:15px}.page-header h2{margin:0 0 6px;color:#1f2937}.page-header p{margin:0;color:#7b8794;font-size:14px}.toolbar{margin-bottom:14px}.title-link{padding:0;border:0;background:none;color:#3370ff;font:inherit;cursor:pointer;text-align:left}.title-link:hover{text-decoration:underline}.danger{color:#f56c6c}.muted{color:#909399;font-size:12px}.calendar-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.calendar-head strong{margin:0 14px;font-size:20px}.office-calendar :deep(.el-calendar-day){height:110px}.day-cell{height:100%;display:flex;flex-direction:column;gap:4px}.day-cell>span{font-weight:600}.event-chip{border:0;text-align:left;border-radius:3px;padding:3px 5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}.event-chip.meeting{background:#dcecff;color:#2468b8}.event-chip.task{background:#def5e8;color:#20865a}.event-chip.reminder{background:#fff0d8;color:#b46b16}.day-cell small{color:#909399}.dashboard{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.dashboard strong{display:block;font-size:28px;color:#3370ff}.dashboard span{color:#7b8794}.ai-quick{margin-top:18px}.ai-quick-head{display:flex;align-items:center;justify-content:space-between;gap:18px}.ai-quick h3{margin:0 0 8px}.ai-quick p{margin:0;color:#7b8794}.meeting-detail{padding:0 8px 10px}.step-panel{padding:18px 0}.step-panel .el-button{margin:10px 8px 0 0}.detail-footer{text-align:right;margin-top:18px}.doc-content{white-space:pre-wrap;max-height:380px;overflow:auto;background:#f7f8fa;padding:14px;line-height:1.7}@media(max-width:900px){.dashboard{grid-template-columns:repeat(2,1fr)}.ai-quick-head{align-items:flex-start;flex-direction:column}}
</style>
